const listAll = `-- name: ListAll :many

SELECT s.id, s.type, s.kind, s.title, s.content, s.data, s.severity, s.report_date, s.status, s.user_id,
       s.submitted_at, s.created_at, s.updated_at, s.reviewed_at, s.review_note,
       u.full_name AS user_name,
       coalesce((SELECT cb.name FROM iam.user_branches b JOIN core.branches cb ON cb.id = b.branch_id
         WHERE b.user_id = s.user_id ORDER BY b.is_primary DESC, cb.name LIMIT 1), '')::text AS branch_name,
       coalesce((SELECT array_agg(r.role ORDER BY r.role) FROM iam.user_roles r WHERE r.user_id = s.user_id), '{}')::text[] AS user_roles,
       rv.full_name AS reviewer_name,
       (SELECT count(*) FROM ops.staff_report_followups f WHERE f.staff_report_id = s.id) AS followups_count,
       count(*) OVER () AS total
FROM ops.staff_reports s
JOIN iam.users u ON u.id = s.user_id
LEFT JOIN iam.users rv ON rv.id = s.reviewed_by
WHERE s.status <> 'draft'
  AND ($1::uuid[] IS NULL
       OR s.user_id = $2::uuid
       OR EXISTS (SELECT 1 FROM iam.user_branches b WHERE b.user_id = s.user_id AND b.branch_id = ANY($1::uuid[])))
  AND ($3::text IS NULL OR s.type = $3::text)
  AND ($4::uuid IS NULL OR s.user_id = $4::uuid)
  AND ($5::uuid IS NULL
       OR EXISTS (SELECT 1 FROM iam.user_branches b WHERE b.user_id = s.user_id AND b.branch_id = $5::uuid))
  AND ($6::date IS NULL OR s.report_date <= $6::date)
  AND ($7::date IS NULL
       OR (s.type NOT IN ('weekly', 'monthly', 'quarterly') AND s.report_date >= $7::date)
       OR (s.type = 'weekly' AND s.report_date >= $7::date - 6)
       OR (s.type = 'monthly' AND s.report_date >= date_trunc('month', $7::date)::date)
       OR (s.type = 'quarterly' AND s.report_date >= date_trunc('quarter', $7::date)::date))
  AND ($8::text IS NULL
       OR ($8::text = 'pending' AND s.type <> 'journal' AND s.status = 'submitted' AND s.reviewed_at IS NULL)
       OR ($8::text = 'done' AND s.type <> 'journal' AND s.reviewed_at IS NOT NULL)
       OR ($8::text = 'returned' AND s.type <> 'journal' AND s.status = 'returned'))
ORDER BY CASE WHEN $9::bool THEN s.updated_at END DESC NULLS LAST, s.report_date DESC, s.id DESC
LIMIT $11 OFFSET $10
`

